pub fn rejection_total(
  lane0: bool,
  lane1: bool,
  lane2: bool,
  lane3: bool) -> u16
{
  (if (lane0) {
    1u16
  } else {
    0u16
  }) +
    (if (lane1) {
      1u16
    } else {
      0u16
    }) +
    (if (lane2) {
      1u16
    } else {
      0u16
    }) +
    (if (lane3) {
      1u16
    } else {
      0u16
    })
}

pub fn saturated_rejection_count(
  count: u16,
  increment: u16) -> u16
{
  if (count >= rejection_limit()) {
    rejection_limit()
  } else {
    if (increment >= rejection_limit() - count) {
      rejection_limit()
    } else {
      count + increment
    }
  }
}

